import { includesIgnoreCase } from "./includesIgnoreCase";
export function removeIncludesIgnoreCase(texts, excludes) {
  return !texts || !texts.length || !excludes || !excludes.length ? texts : texts.filter(function (text) {
    return !excludes.some(function (exclude) {
      return includesIgnoreCase(text, exclude);
    });
  });
}