export function toFloat(source, defaultValue) {
  if (source === undefined || source === null) {
    return defaultValue;
  }
  if (typeof source === 'number') {
    return source;
  }
  try {
    var result = Number.parseFloat(source);
    return Number.isNaN(result) ? defaultValue : result;
  } catch (_unused) {}
  return defaultValue;
}