import { equalsIgnoreCase } from "./equalsIgnoreCase";
export function removeEqualsIgnoreCase(texts, excludes) {
  return !texts || !texts.length || !excludes || !excludes.length ? texts : texts.filter(function (text) {
    return !excludes.some(function (exclude) {
      return equalsIgnoreCase(text, exclude);
    });
  });
}